/**
 * @file build/cliWrapper.js
 * @description Writes the tritium_cli command into a packaged app (called from
 * the afterPack hook).
 *
 * `tritium/cli/dist/tritium_cli.mjs` (built by the cli package) is copied to `<resources>/cli/` by extraResources;
 * this adds the command next to it: `tritium_cli` (sh) on macOS and Linux,
 * `tritium_cli.cmd` on Windows. Both run the script in the app's own
 * executable as Node (ELECTRON_RUN_AS_NODE, the way VS Code's `code` command
 * works), so nothing but the app has to be installed. That needs the RunAsNode
 * fuse left on (it is: no fuses are set).
 *
 * Generated here rather than kept as files because the path to the executable
 * is the packager's to decide (on Linux it is derived from the package name).
 */
const fs = require('node:fs');
const path = require('node:path');

const SCRIPT = 'tritium_cli.mjs';

/**
 * The sh wrapper. Follows symlinks first, so a link on PATH (or the .deb's
 * /usr/bin/tritium_cli) finds the app it points into.
 *
 * @param {string} exeFromCli - the executable, relative to `<resources>/cli`
 */
function shWrapper(exeFromCli) {
  return `#!/bin/sh
# tritium_cli: CueMol3's command line (generated by build/cliWrapper.js).
self=$0
while [ -L "$self" ]; do
  link=$(readlink "$self")
  case $link in
    /*) self=$link ;;
    *) self=$(dirname "$self")/$link ;;
  esac
done
dir=$(cd "$(dirname "$self")" && pwd)
ELECTRON_RUN_AS_NODE=1 exec "$dir/${exeFromCli}" "$dir/${SCRIPT}" "$@"
`;
}

/** The Windows wrapper; `exeFromCli` uses backslashes. */
function cmdWrapper(exeFromCli) {
  return `@echo off\r
rem tritium_cli: CueMol3's command line (generated by build/cliWrapper.js).\r
setlocal\r
set ELECTRON_RUN_AS_NODE=1\r
"%~dp0${exeFromCli}" "%~dp0${SCRIPT}" %*\r
exit /b %ERRORLEVEL%\r
`;
}

/**
 * Write the wrapper for `context` (the afterPack context).
 *
 * @returns {string} the path written
 */
function writeCliWrapper(context) {
  const { appOutDir, electronPlatformName, packager } = context;
  const productFilename = packager.appInfo.productFilename;
  let cliDir;
  let file;
  let body;
  if (electronPlatformName === 'darwin') {
    cliDir = path.join(appOutDir, `${productFilename}.app`, 'Contents', 'Resources', 'cli');
    file = 'tritium_cli';
    body = shWrapper(`../../MacOS/${productFilename}`);
  } else if (electronPlatformName === 'win32') {
    cliDir = path.join(appOutDir, 'resources', 'cli');
    file = 'tritium_cli.cmd';
    body = cmdWrapper(`..\\..\\${productFilename}.exe`);
  } else {
    cliDir = path.join(appOutDir, 'resources', 'cli');
    file = 'tritium_cli';
    body = shWrapper(`../../${packager.executableName}`);
  }
  if (!fs.existsSync(path.join(cliDir, SCRIPT))) {
    throw new Error(`afterPack: ${SCRIPT} not found in ${cliDir} (extraResources)`);
  }
  const out = path.join(cliDir, file);
  fs.writeFileSync(out, body, { mode: 0o755 });
  // writeFileSync's mode only applies to a new file.
  fs.chmodSync(out, 0o755);
  return out;
}

module.exports = { writeCliWrapper, shWrapper, cmdWrapper };
